CREATE TABLE `user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(100) NOT NULL COMMENT '登录账号/手机号',
  `email` varchar(100) DEFAULT NULL,
  `password` varchar(100) NOT NULL COMMENT '加密后的密码',
  `name` varchar(100) DEFAULT NULL COMMENT '员工姓名',
  `id_num` varchar(100) DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0禁用',
  `create_time` bigint NOT NULL COMMENT '创建时间',
  `update_time` bigint NOT NULL COMMENT '更新时间',
  `merchant_id` bigint DEFAULT NULL,
  `is_approval` tinyint DEFAULT '1',
  `update_by` bigint DEFAULT NULL,
  `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统用户表';
